<?php
declare(strict_types=1);
session_start();
$configFile = __DIR__.'/snakegram-config.php';
if (!is_file($configFile)) { http_response_code(503); exit('Crie macos-406/snakegram-config.php a partir de snakegram-config.example.php.'); }
$config = require $configFile; $password = (string)($config['admin_password'] ?? '');
if ($password === '' || str_starts_with($password,'TROQUE-')) { http_response_code(503); exit('Defina uma senha forte em snakegram-config.php.'); }
$dataDir=__DIR__.'/data'; $pendingDir=__DIR__.'/uploads/pending'; $photosDir=__DIR__.'/photos';
foreach ([$dataDir,$pendingDir,$photosDir] as $dir) if (!is_dir($dir)) @mkdir($dir,0755,true);
$dataFile=$dataDir.'/snakegram-posts.json';
function all_posts(string $file): array { $v=is_file($file)?json_decode((string)file_get_contents($file),true):[]; return is_array($v)?$v:[]; }
function put_posts(string $file,array $posts): bool { $h=fopen($file,'c+'); if(!$h||!flock($h,LOCK_EX))return false; $v=json_encode($posts,JSON_UNESCAPED_SLASHES|JSON_INVALID_UTF8_SUBSTITUTE); rewind($h);ftruncate($h,0);$ok=$v!==false&&fwrite($h,$v)!==false;fflush($h);flock($h,LOCK_UN);fclose($h);return $ok; }
if (isset($_POST['login'])) { if (hash_equals($password,(string)($_POST['password']??''))) $_SESSION['snakegram_admin']=true; else $error='Senha incorreta.'; }
if (isset($_GET['logout'])) { session_destroy(); header('Location: snakegram-admin.php'); exit; }
if (!($_SESSION['snakegram_admin']??false)) { ?><!doctype html><meta name="viewport" content="width=device-width,initial-scale=1"><style>body{margin:0;min-height:100vh;display:grid;place-items:center;background:#090909;color:#fff;font-family:Arial}form{width:min(360px,88vw);padding:28px;border:1px solid #ffffff26;border-radius:16px;background:#151515}input,button{width:100%;box-sizing:border-box;padding:12px;margin-top:12px;border-radius:8px;border:0}button{background:#e54837;font-weight:800}</style><form method="post"><h1>Snakegram</h1><p>Painel de moderação</p><?php if(isset($error))echo '<p>'.$error.'</p>';?><input name="password" type="password" placeholder="Senha do painel" required autofocus><button name="login">Entrar</button></form><?php exit; }
$posts=all_posts($dataFile);
if ($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['action'],$_POST['id'])) { foreach($posts as &$post){ if(($post['id']??'')!==$_POST['id']||($post['status']??'')!=='pending')continue; $from=$pendingDir.'/'.basename((string)$post['file']); if($_POST['action']==='approve'&&is_file($from)){ $to=$photosDir.'/'.basename((string)$post['file']); if(rename($from,$to)){$post['status']='approved';$post['approved_at']=gmdate('c');} } elseif($_POST['action']==='reject'){if(is_file($from))@unlink($from);$post['status']='rejected';$post['rejected_at']=gmdate('c');} } unset($post); put_posts($dataFile,$posts); header('Location: snakegram-admin.php'); exit; }
$pending=array_values(array_filter($posts,fn($p)=>($p['status']??'')==='pending'));
?><!doctype html><html lang="pt-BR"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Snakegram — Moderação</title><style>body{margin:0;background:#090909;color:#fff;font-family:Arial}main{max-width:1050px;margin:auto;padding:28px}header{display:flex;justify-content:space-between;align-items:center;margin-bottom:22px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:16px}.post{padding:12px;border:1px solid #ffffff26;border-radius:14px;background:#151515}.post img,.post video{width:100%;height:220px;object-fit:contain;background:#000;border-radius:9px}.meta{font-size:13px;color:#bbb;margin:10px 0}button,a{border:0;border-radius:8px;padding:10px 12px;font-weight:800;text-decoration:none}.approve{background:#1ed760}.reject{background:#ec4738;color:#fff}@media(max-width:600px){main{padding:16px}.post img,.post video{height:180px}}</style><main><header><div><h1>Snakegram</h1><p><?=count($pending)?> post(s) aguardando análise</p></div><a href="?logout=1">Sair</a></header><div class="grid"><?php foreach($pending as $post):$file=htmlspecialchars((string)$post['file']);$author=htmlspecialchars((string)$post['author']);$isVideo=($post['type']??'')==='video';?><article class="post"><?php if($isVideo):?><video src="uploads/pending/<?=$file?>" controls preload="metadata"></video><?php else:?><img src="uploads/pending/<?=$file?>" alt="Post pendente"><?php endif;?><div class="meta"><?=$author?><br><?=htmlspecialchars((string)($post['created_at']??''))?></div><form method="post"><input type="hidden" name="id" value="<?=htmlspecialchars((string)$post['id'])?>"><button class="approve" name="action" value="approve">Aprovar</button><button class="reject" name="action" value="reject">Reprovar</button></form></article><?php endforeach;if(!$pending)echo '<p>Nenhum post pendente.</p>'?></div></main></html>
